#!/usr/bin/env python3
"""drug/chem_id_validate — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "chem_id_validate"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'chem_id_validate', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """RDKit SMILES sanitize + InChI canonical + 同分异构对比。
    输入:smiles (str) | smiles_list (list)
    输出:canonical / inchi / inchi_key / valid / 化学合法性诊断
    """
    import os as _os
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    smiles_list = payload.get("smiles_list") or ([payload.get("smiles")] if payload.get("smiles") else [])
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE, "n_input": len(smiles_list)}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "results": [], "n_valid": 0,
                "diagnostics": {**diagnostics, "dry": True}}
    if not smiles_list:
        return {"ok": False, "error": "需要 smiles 或 smiles_list", "diagnostics": diagnostics}

    script = (
        "import json, sys\n"
        "from rdkit import Chem\n"
        "from rdkit.Chem.inchi import MolToInchi, MolToInchiKey\n"
        f"smis = {smiles_list!r}\n"
        "results = []\n"
        "for s in smis:\n"
        "    if not s:\n"
        "        results.append({'input': s, 'valid': False, 'error': 'empty'}); continue\n"
        "    try:\n"
        "        m = Chem.MolFromSmiles(s)\n"
        "        if m is None: results.append({'input': s, 'valid': False, 'error': 'parse_fail'}); continue\n"
        "        Chem.SanitizeMol(m)\n"
        "        canon = Chem.MolToSmiles(m)\n"
        "        inchi = MolToInchi(m); ikey = MolToInchiKey(m)\n"
        "        results.append({'input': s, 'valid': True, 'canonical': canon, 'inchi': inchi, 'inchi_key': ikey})\n"
        "    except Exception as e:\n"
        "        results.append({'input': s, 'valid': False, 'error': repr(e)[:100]})\n"
        "json.dump({'results': results, 'n_valid': sum(1 for r in results if r['valid'])}, sys.stdout)\n"
    )
    r = run_tool(["python3", "-c", script], timeout=60)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "rdkit 调用失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
